// _signed_cloneMapIntString returns a copy of x, a map[int]string, and nil for
// a nil x.
func _signed_cloneMapIntString(x map[int]string) map[int]string {
	if x == nil {
		return nil
	}
	c := make(map[int]string, len(x))
	for mk, mv := range x {
		c[mk] = strings.Clone(mv)
	}
	return c
}

